package com.playerstatssync;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;

public class PlayerStatsSyncPanel extends PluginPanel implements SyncService.SyncStatusListener
{
    private static final String WEBSITE_URL = "https://osrs-duels.vercel.app";

    private final PlayerStatsSyncPlugin plugin;
    private final PlayerStatsSyncConfig config;

    private final JLabel statusLabel;
    private final JLabel lastSyncLabel;
    private final JLabel errorLabel;
    private final JButton syncButton;
    private final JPanel statusIndicator;
    private final JLabel apiKeyLabel;
    private final JLabel syncEnabledLabel;
    private final JLabel intervalLabel;
    private final JPanel setupPanel;

    private static final Color STATUS_CONNECTED = new Color(0, 200, 83);
    private static final Color STATUS_SYNCING = new Color(255, 193, 7);
    private static final Color STATUS_DISCONNECTED = new Color(158, 158, 158);
    private static final Color STATUS_ERROR = new Color(244, 67, 54);

    private static final DateTimeFormatter TIME_FORMAT = DateTimeFormatter.ofPattern("HH:mm:ss")
        .withZone(ZoneId.systemDefault());

    public PlayerStatsSyncPanel(PlayerStatsSyncPlugin plugin, PlayerStatsSyncConfig config)
    {
        this.plugin = plugin;
        this.config = config;

        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBorder(new EmptyBorder(10, 10, 10, 10));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        // Header
        JLabel titleLabel = new JLabel("Player Stats Sync");
        titleLabel.setForeground(Color.WHITE);
        titleLabel.setFont(titleLabel.getFont().deriveFont(Font.BOLD, 16f));
        titleLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(titleLabel);
        add(Box.createVerticalStrut(15));

        // Setup instructions panel (shown when no API key)
        setupPanel = new JPanel();
        setupPanel.setLayout(new BoxLayout(setupPanel, BoxLayout.Y_AXIS));
        setupPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        setupPanel.setBorder(new EmptyBorder(10, 10, 10, 10));
        setupPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel setupTitle = new JLabel("Getting Started");
        setupTitle.setForeground(Color.WHITE);
        setupTitle.setFont(setupTitle.getFont().deriveFont(Font.BOLD, 13f));
        setupTitle.setAlignmentX(Component.LEFT_ALIGNMENT);
        setupPanel.add(setupTitle);
        setupPanel.add(Box.createVerticalStrut(8));

        JLabel setupText = new JLabel(
            "<html><body style='width: 160px'>"
            + "To get started, create an account and get your API Sync Key at the website below."
            + "<br><br>"
            + "Then paste your key into the <b>API Sync Key</b> field in the plugin settings."
            + "</body></html>"
        );
        setupText.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        setupText.setAlignmentX(Component.LEFT_ALIGNMENT);
        setupPanel.add(setupText);
        setupPanel.add(Box.createVerticalStrut(8));

        JButton setupWebsiteButton = new JButton("Get API Key");
        setupWebsiteButton.setFocusPainted(false);
        setupWebsiteButton.setAlignmentX(Component.LEFT_ALIGNMENT);
        setupWebsiteButton.addActionListener(e -> LinkBrowser.browse(WEBSITE_URL));
        setupPanel.add(setupWebsiteButton);

        add(setupPanel);
        add(Box.createVerticalStrut(10));

        // Status section
        JPanel statusRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 5, 0));
        statusRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        statusRow.setAlignmentX(Component.LEFT_ALIGNMENT);

        statusIndicator = new JPanel();
        statusIndicator.setPreferredSize(new Dimension(12, 12));
        statusIndicator.setBackground(STATUS_DISCONNECTED);
        statusRow.add(statusIndicator);

        statusLabel = new JLabel("Disconnected");
        statusLabel.setForeground(Color.WHITE);
        statusRow.add(statusLabel);

        add(statusRow);
        add(Box.createVerticalStrut(10));

        // Last sync row
        JPanel lastSyncRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
        lastSyncRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        lastSyncRow.setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel lastSyncTitleLabel = new JLabel("Last sync: ");
        lastSyncTitleLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        lastSyncRow.add(lastSyncTitleLabel);

        lastSyncLabel = new JLabel("Never");
        lastSyncLabel.setForeground(Color.WHITE);
        lastSyncRow.add(lastSyncLabel);

        add(lastSyncRow);
        add(Box.createVerticalStrut(5));

        // Sync interval row
        JPanel intervalRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
        intervalRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        intervalRow.setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel intervalTitleLabel = new JLabel("Interval: ");
        intervalTitleLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        intervalRow.add(intervalTitleLabel);

        intervalLabel = new JLabel(config.syncIntervalSeconds() + "s");
        intervalLabel.setForeground(Color.WHITE);
        intervalRow.add(intervalLabel);

        add(intervalRow);
        add(Box.createVerticalStrut(10));

        // Error label
        errorLabel = new JLabel("");
        errorLabel.setForeground(STATUS_ERROR);
        errorLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        errorLabel.setVisible(false);
        add(errorLabel);

        // Configuration info
        JPanel configPanel = new JPanel();
        configPanel.setLayout(new BoxLayout(configPanel, BoxLayout.Y_AXIS));
        configPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        configPanel.setBorder(new EmptyBorder(10, 10, 10, 10));
        configPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel configTitle = new JLabel("Configuration");
        configTitle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        configTitle.setFont(configTitle.getFont().deriveFont(Font.BOLD));
        configTitle.setAlignmentX(Component.LEFT_ALIGNMENT);
        configPanel.add(configTitle);
        configPanel.add(Box.createVerticalStrut(5));

        apiKeyLabel = new JLabel("");
        apiKeyLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        configPanel.add(apiKeyLabel);

        syncEnabledLabel = new JLabel("");
        syncEnabledLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        configPanel.add(syncEnabledLabel);

        add(configPanel);
        add(Box.createVerticalStrut(10));

        // Sync button
        syncButton = new JButton("Sync Now");
        syncButton.setFocusPainted(false);
        syncButton.setAlignmentX(Component.LEFT_ALIGNMENT);
        syncButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, syncButton.getPreferredSize().height));
        syncButton.addActionListener(e -> {
            syncButton.setEnabled(false);
            syncButton.setText("Syncing...");
            plugin.forceSync();

            Timer timer = new Timer(2000, evt -> {
                syncButton.setEnabled(true);
                syncButton.setText("Sync Now");
            });
            timer.setRepeats(false);
            timer.start();
        });
        add(syncButton);
        add(Box.createVerticalStrut(10));

        // Website link (always visible)
        JButton websiteButton = new JButton("Open Website");
        websiteButton.setFocusPainted(false);
        websiteButton.setAlignmentX(Component.LEFT_ALIGNMENT);
        websiteButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, websiteButton.getPreferredSize().height));
        websiteButton.addActionListener(e -> LinkBrowser.browse(WEBSITE_URL));
        add(websiteButton);

        // Initialize labels and setup visibility
        refreshConfigLabels();
    }

    public void refreshConfigLabels()
    {
        boolean needsSetup = config.apiSyncKey().isEmpty();
        setupPanel.setVisible(needsSetup);
        syncButton.setEnabled(!needsSetup);

        String apiKeyStatus = needsSetup ? "Not set" : "Configured";
        apiKeyLabel.setText("API Key: " + apiKeyStatus);
        apiKeyLabel.setForeground(needsSetup ? STATUS_ERROR : STATUS_CONNECTED);

        syncEnabledLabel.setText("Sync: " + (config.syncEnabled() ? "Enabled" : "Disabled"));
        syncEnabledLabel.setForeground(config.syncEnabled() ? STATUS_CONNECTED : STATUS_DISCONNECTED);

        intervalLabel.setText(config.syncIntervalSeconds() + "s");
    }

    @Override
    public void onStatusChange(SyncService.SyncStatus status, long lastSyncTime, String error)
    {
        SwingUtilities.invokeLater(() -> {
            switch (status)
            {
                case CONNECTED:
                    statusIndicator.setBackground(STATUS_CONNECTED);
                    statusLabel.setText("Connected");
                    errorLabel.setVisible(false);
                    break;
                case SYNCING:
                    statusIndicator.setBackground(STATUS_SYNCING);
                    statusLabel.setText("Syncing...");
                    break;
                case DISCONNECTED:
                    statusIndicator.setBackground(STATUS_DISCONNECTED);
                    statusLabel.setText("Disconnected");
                    break;
                case ERROR:
                    statusIndicator.setBackground(STATUS_ERROR);
                    statusLabel.setText("Error");
                    if (error != null)
                    {
                        String escaped = error.replace("&", "&amp;")
                            .replace("<", "&lt;")
                            .replace(">", "&gt;")
                            .replace("\"", "&quot;");
                        errorLabel.setText("<html><body style='width: 150px'>" + escaped + "</body></html>");
                        errorLabel.setVisible(true);
                    }
                    break;
            }

            if (lastSyncTime > 0)
            {
                lastSyncLabel.setText(TIME_FORMAT.format(Instant.ofEpochMilli(lastSyncTime)));
            }

            refreshConfigLabels();
        });
    }
}

package com.playerstatssync.models;

import java.util.Map;

public class SyncPayload
{
    private String rsn;
    private long timestamp;
    private int combatLevel;
    private Map<String, SkillData> skills;

    public SyncPayload() {}

    public String getRsn() { return rsn; }
    public void setRsn(String rsn) { this.rsn = rsn; }

    public long getTimestamp() { return timestamp; }
    public void setTimestamp(long timestamp) { this.timestamp = timestamp; }

    public int getCombatLevel() { return combatLevel; }
    public void setCombatLevel(int combatLevel) { this.combatLevel = combatLevel; }

    public Map<String, SkillData> getSkills() { return skills; }
    public void setSkills(Map<String, SkillData> skills) { this.skills = skills; }

    public static Builder builder() { return new Builder(); }

    public static class Builder
    {
        private final SyncPayload payload = new SyncPayload();

        public Builder rsn(String rsn) { payload.rsn = rsn; return this; }
        public Builder timestamp(long timestamp) { payload.timestamp = timestamp; return this; }
        public Builder combatLevel(int combatLevel) { payload.combatLevel = combatLevel; return this; }
        public Builder skills(Map<String, SkillData> skills) { payload.skills = skills; return this; }
        public SyncPayload build() { return payload; }
    }
}

