import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import okhttp3.OkHttpClient;

import javax.inject.Inject;
import javax.swing.SwingUtilities;
import java.awt.image.BufferedImage;
import java.util.concurrent.ScheduledExecutorService;

@PluginDescriptor(
    name = "Player Stats Sync",
    description = "Syncs your player stats to a web dashboard",
    tags = {"sync", "skills", "stats", "dashboard"}
)
public class PlayerStatsSyncPlugin extends Plugin
{
    private static final Logger log = LoggerFactory.getLogger(PlayerStatsSyncPlugin.class);

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private PlayerStatsSyncConfig config;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private OkHttpClient okHttpClient;

    @Inject
    private Gson gson;

    @Inject
    private ScheduledExecutorService executor;

    private DataCollector dataCollector;
    private SyncService syncService;
    private PlayerStatsSyncPanel panel;
    private NavigationButton navButton;

    private volatile boolean periodicSyncStarted = false;

    @Override
    protected void startUp() throws Exception
    {
        log.info("Player Stats Sync starting up");

        dataCollector = new DataCollector(client);
        syncService = new SyncService(config, gson, okHttpClient, executor);

        panel = new PlayerStatsSyncPanel(this, config);
        syncService.setStatusListener(panel);

        BufferedImage icon;
        try
        {
            icon = ImageUtil.loadImageResource(getClass(), "/com/playerstatssync/icon.png");
        }
        catch (Exception e)
        {
            log.debug("Could not load icon, using default");
            icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        }

        navButton = NavigationButton.builder()
            .tooltip("Player Stats Sync")
            .icon(icon)
            .priority(10)
            .panel(panel)
            .build();

        clientToolbar.addNavigation(navButton);
    }

    @Override
    protected void shutDown() throws Exception
    {
        log.info("Player Stats Sync shutting down");

        clientToolbar.removeNavigation(navButton);
        syncService.shutdown();
        periodicSyncStarted = false;
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!"playerstatssync".equals(event.getGroup()))
        {
            return;
        }

        if ("syncIntervalSeconds".equals(event.getKey()) && periodicSyncStarted)
        {
            log.info("Sync interval changed, restarting periodic sync");
            syncService.startPeriodicSync(this::doPeriodicSync);
        }

        SwingUtilities.invokeLater(() -> panel.refreshConfigLabels());
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            if (!periodicSyncStarted)
            {
                clientThread.invokeLater(() -> {
                    if (dataCollector.hasData())
                    {
                        log.info("Logged in, starting periodic sync");
                        periodicSyncStarted = true;
                        syncService.startPeriodicSync(this::doPeriodicSync);
                    }
                });
            }
        }
        else if (event.getGameState() == GameState.LOGIN_SCREEN)
        {
            periodicSyncStarted = false;
            syncService.stopPeriodicSync();
        }
    }

    private void doPeriodicSync()
    {
        clientThread.invokeLater(() -> {
            if (dataCollector.hasData())
            {
                SyncPayload payload = dataCollector.collectFullPayload();
                if (payload != null)
                {
                    syncService.forceSync(payload);
                }
            }
        });
    }

    public void forceSync()
    {
        if (config.apiSyncKey().isEmpty())
        {
            log.warn("Cannot sync - no API key configured");
            return;
        }

        clientThread.invokeLater(() -> {
            if (!dataCollector.hasData())
            {
                log.warn("Cannot sync - no player data available");
                return;
            }

            SyncPayload payload = dataCollector.collectFullPayload();
            if (payload != null)
            {
                syncService.forceSync(payload);
            }
        });
    }

    @Provides
    PlayerStatsSyncConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(PlayerStatsSyncConfig.class);
    }
}

package com.playerstatssync;

import com.playerstatssync.models.SyncPayload;
import com.google.gson.Gson;
import net.runelite.client.RuneLite;
import okhttp3.Call;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.zip.GZIPOutputStream;

public class SyncService
{
    private static final Logger log = LoggerFactory.getLogger(SyncService.class);

    private static final String USER_AGENT = RuneLite.USER_AGENT + " (PlayerStatsSync)";
    private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");
    private static final MediaType GZIP_JSON = MediaType.get("application/json");
    private static final int GZIP_THRESHOLD = 5 * 1024; // 5KB

    private final OkHttpClient httpClient;
    private final Gson gson;
    private final PlayerStatsSyncConfig config;
    private final ScheduledExecutorService executor;

    private ScheduledFuture<?> periodicSync;
    private volatile SyncStatus status = SyncStatus.DISCONNECTED;
    private volatile long lastSyncTime = 0;
    private volatile String lastError = null;
    private volatile SyncStatusListener statusListener;

    public enum SyncStatus
    {
        CONNECTED,
        SYNCING,
        DISCONNECTED,
        ERROR
    }

    public interface SyncStatusListener
    {
        void onStatusChange(SyncStatus status, long lastSyncTime, String error);
    }

    public SyncService(PlayerStatsSyncConfig config, Gson gson, OkHttpClient okHttpClient, ScheduledExecutorService executor)
    {
        this.config = config;
        this.gson = gson;
        this.executor = executor;

        // Create a derived client with custom timeouts (shares connection pool with RuneLite)
        this.httpClient = okHttpClient.newBuilder()
            .connectTimeout(30, TimeUnit.SECONDS)
            .readTimeout(30, TimeUnit.SECONDS)
            .writeTimeout(30, TimeUnit.SECONDS)
            .build();
    }

    public void setStatusListener(SyncStatusListener listener)
    {
        this.statusListener = listener;
    }

    public synchronized void startPeriodicSync(Runnable syncTask)
    {
        stopPeriodicSync();

        int intervalSeconds = config.syncIntervalSeconds();
        log.info("Starting periodic sync every {} seconds", intervalSeconds);

        periodicSync = executor.scheduleAtFixedRate(() -> {
            try
            {
                if (!config.syncEnabled() || config.apiSyncKey().isEmpty())
                {
                    return;
                }

                log.debug("Periodic sync tick firing");
                syncTask.run();
            }
            catch (Exception e)
            {
                log.error("Periodic sync task error", e);
            }
        }, intervalSeconds, intervalSeconds, TimeUnit.SECONDS);
    }

    public synchronized void stopPeriodicSync()
    {
        if (periodicSync != null)
        {
            periodicSync.cancel(false);
            periodicSync = null;
            log.info("Stopped periodic sync");
        }
    }

    public void forceSync(SyncPayload payload)
    {
        if (config.apiSyncKey().isEmpty())
        {
            log.debug("No API key configured, skipping sync");
            return;
        }

        sendSync(payload);
    }

    private void sendSync(SyncPayload payload)
    {
        updateStatus(SyncStatus.SYNCING, null);

        String json = gson.toJson(payload);
        byte[] body = json.getBytes(StandardCharsets.UTF_8);
        boolean useGzip = body.length > GZIP_THRESHOLD;

        RequestBody requestBody;
        Request.Builder requestBuilder = new Request.Builder()
            .url(config.apiBaseUrl() + "/api/sync")
            .header("User-Agent", USER_AGENT)
            .header("Authorization", "Bearer " + config.apiSyncKey());

        if (useGzip)
        {
            try
            {
                byte[] gzipped = gzip(body);
                requestBody = RequestBody.create(GZIP_JSON, gzipped);
                requestBuilder.header("Content-Encoding", "gzip");
                log.debug("Using GZIP compression: {} -> {} bytes", body.length, gzipped.length);
            }
            catch (IOException e)
            {
                log.error("Failed to GZIP payload", e);
                requestBody = RequestBody.create(JSON, body);
            }
        }
        else
        {
            requestBody = RequestBody.create(JSON, body);
        }

        Request request = requestBuilder.post(requestBody).build();

        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                log.error("Sync failed", e);
                updateStatus(SyncStatus.ERROR, e.getMessage());
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try
                {
                    if (response.isSuccessful())
                    {
                        lastSyncTime = System.currentTimeMillis();
                        updateStatus(SyncStatus.CONNECTED, null);
                        log.debug("Sync successful for {}", payload.getRsn());
                    }
                    else
                    {
                        String errorBody = response.body() != null ? response.body().string() : "Unknown error";
                        if (errorBody.length() > 500)
                        {
                            errorBody = errorBody.substring(0, 500);
                        }
                        log.error("Sync failed with status {}: {}", response.code(), errorBody);
                        updateStatus(SyncStatus.ERROR, "HTTP " + response.code() + ": " + errorBody);
                    }
                }
                catch (IOException e)
                {
                    log.error("Error reading response", e);
                    updateStatus(SyncStatus.ERROR, e.getMessage());
                }
                finally
                {
                    response.close();
                }
            }
        });
    }

    private void updateStatus(SyncStatus newStatus, String error)
    {
        this.status = newStatus;
        this.lastError = error;

        SyncStatusListener listener = this.statusListener;
        if (listener != null)
        {
            listener.onStatusChange(status, lastSyncTime, lastError);
        }
    }

    private byte[] gzip(byte[] data) throws IOException
    {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (GZIPOutputStream gzos = new GZIPOutputStream(baos))
        {
            gzos.write(data);
        }
        return baos.toByteArray();
    }

    public SyncStatus getStatus()
    {
        return status;
    }

    public long getLastSyncTime()
    {
        return lastSyncTime;
    }

    public String getLastError()
    {
        return lastError;
    }

    public synchronized void shutdown()
    {
        stopPeriodicSync();
        statusListener = null;
    }
}

package com.playerstatssync;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("playerstatssync")
public interface PlayerStatsSyncConfig extends Config
{
    @ConfigItem(
        keyName = "apiSyncKey",
        name = "API Sync Key",
        description = "The API key used to authenticate with the server",
        position = 1,
        secret = true
    )
    default String apiSyncKey()
    {
        return "";
    }

    @ConfigItem(
        keyName = "apiBaseUrl",
        name = "API Base URL",
        description = "The base URL of the API server",
        position = 2
    )
    default String apiBaseUrl()
    {
        return "http://localhost:8080";
    }

    @ConfigItem(
